export function sanitizeInput(input: string): string {
  const replacements: Record<string, string> = {
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;'
  };

  return input.replace(/[<>"']/g, (char) => replacements[char] ?? char);
}

